{
  "name": "shared-session",
  "displayName": "Shared Sessions",
  "version": "0.11.53",
  "description": "Share a Claude Code session with a link, or with your team. Teammates join from their own Claude Code and talk to it: one session does the work, everyone sees every turn live, and the host approves what runs on their machine. Sign in with GitHub or Google for teams: your team's live sessions, one press to join. Sharing goes through this project's public server unless you set your own (README: Privacy and the public server).",
  "author": {
    "name": "scoootscooob",
    "url": "https://github.com/scoootscooob"
  },
  "homepage": "https://github.com/Paradigm-Study/claude-share",
  "repository": "https://github.com/Paradigm-Study/claude-share",
  "license": "MIT",
  "keywords": [
    "collaboration",
    "multiplayer",
    "share",
    "pair-programming",
    "teams",
    "sessions"
  ],
  "types": "./types/index.d.ts",
  "userConfig": {
    "server": {
      "type": "string",
      "title": "Share server",
      "description": "Leave empty to share through the public server. To use your own, its https address (README: \"Host a server\"). Joining a link always uses the server in that link."
    }
  },
  "mcpServers": {
    "traces": {
      "command": "node",
      "args": [
        "${CLAUDE_PLUGIN_ROOT}/relay/traces-mcp.mts"
      ],
      "env": {
        "SHARED_SESSION_OPTION_SERVER": "${user_config.server}"
      }
    }
  }
}
